package com.serbekun.mgdsw.http.handles;

import com.serbekun.mgdsw.BuildInfo;
import com.serbekun.mgdsw.http.HttpHandler;

import io.javalin.config.JavalinConfig;

import com.serbekun.mgdsw.domain.http.ApiV0VersionRes;

/**
 * Build version endpoint: {@code GET /api/v0/version}.
 *
 * <p>Returns the version of the running build as a JSON object. The value is
 * read from {@link BuildInfo}, which loads {@code version.properties}
 * generated by Gradle at build time.
 *
 * <p>Needed to identify which build is deployed, to diagnose issues and to let
 * clients or operators check whether an update is available.
 *
 * <p>Request: no path or query parameters and no body.
 *
 * <p>Response: {@code 200 OK}, {@code Content-Type: application/json}
 * <pre>{@code
 * {"version": "<server build version>"}
 * }</pre>
 */
public class ApiV0Version implements HttpHandler {
    
    @Override 
    public void register(JavalinConfig config) {
        config.routes.get("/api/v0/version", ctx -> {
            ctx.json(new ApiV0VersionRes(BuildInfo.version()));
        });
    }
}
